#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, b;
    cin >> n >> b;
    vector<int> arr1(n);
    for (int i = 0; i < n; i++) {
        cin >> arr1[i];
    }

    vector<int> prefixEven(n, 0), prefixOdd(n, 0);
    int evenCount = 0, oddCount = 0;
    for (int i = 0; i < n; i++) {
        if (arr1[i] % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }
        prefixEven[i] = evenCount;
        prefixOdd[i] = oddCount;
    }

    vector<int> diffList;
    int prevIndex = 0;
    for (int i = 1; i < n - 2; i += 2) {
        int x, y;
        if (prevIndex == 0) {
            x = prefixEven[i];
            y = prefixOdd[i];
        } else {
            x = prefixEven[i] - prefixEven[prevIndex];
            y = prefixOdd[i] - prefixOdd[prevIndex];
        }
        if (x == y) {
            diffList.push_back(abs(arr1[i + 1] - arr1[i]));
            prevIndex = i;
        }
    }

    int p = (int)diffList.size();
    vector<int> arr(p);
    for (int i = 0; i < p; i++) {
        arr[i] = diffList[i];
    }

    vector<int> val(p, 1);
    vector<vector<int>> table(p + 1, vector<int>(b + 1, 0));

    for (int i = 1; i <= p; i++) {
        for (int w = 0; w <= b; w++) {
            if (arr[i - 1] <= w) {
                table[i][w] = std::max(val[i - 1] + table[i - 1][w - arr[i - 1]], table[i - 1][w]);
            } else {
                table[i][w] = table[i - 1][w];
            }
        }
    }

    cout << table[p][b] << "\n";

    return 0;
}
